import{_ as e,o as a,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"DAO中的方法与mapper","description":"","frontmatter":{"title":"DAO中的方法与mapper","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/DAO中的方法与mapper.md","filePath":"posts/java快速入门/附录/未分类/DAO中的方法与mapper.md"}'),u={name:"posts/java快速入门/附录/未分类/DAO中的方法与mapper.md"};function p(l,t,r,i,g,s){return a(),o("div",null,[...t[0]||(t[0]=[n('<div><p>getCount 方法的具体实现通常在 MyBatis 的 Mapper XML 文件中。这个 XML 文件通常与你的 DAO 接口（在这个例子中是 ProjectManagementDao）在同一个包下，并且它们的名字通常是相同的。在这个 XML 文件中，你将会看到一个与 getCount 方法相对应的 &lt;select&gt; 标签。在这个标签里，会有一个 SQL 语句来执行实际的数据库操作。这就是 MyBatis 的工作方式，即将 SQL 语句和 Java 代码分开，使得你的代码更容易阅读和维护。</p><p>你应该找到一个类似于 ProjectManagementDao.xml 的文件，并在其中找到类似下面的内容： &lt;select id=&quot;getCount&quot; parameterType=&quot;map&quot; resultType=&quot;com.zhsl.sgc.vo.ManagementCountVo&quot;&gt; -- 这里是具体的 SQL 语句 &lt;/select&gt; 以上的 id 与 parameterType 属性对应于 getCount 方法的名称和参数，resultType 对应于 getCount 方法的返回类型。</p><p>如果你无法在项目中找到对应的 Mapper XML 文件，那可能是使用了 MyBatis 的注解功能。在这种情况下，具体的 SQL 语句会以注解的形式直接写在 DAO 接口的方法上。例如： @Select(&quot;SELECT ...&quot;) ManagementCountVo getCount(@Param(&quot;countYear&quot;) String countYear, @Param(&quot;countRegion&quot;) String countRegion); 请注意，我上面只是举例，具体的 SQL 语句会根据实际需求编写。</p><p>具体实现代码： package com.aoip.base.dao;</p><p>import com.baomidou.mybatisplus.core.mapper.BaseMapper;</p><p>public interface BaseDao&lt;T&gt; extends BaseMapper&lt;T&gt; { }</p><p>packagecom.aoip.base.dao;</p><p>importcom.aoip.orm.mybatis.datascope.DataScope; importcom.baomidou.mybatisplus.core.conditions.Wrapper; importcom.baomidou.mybatisplus.core.metadata.IPage; importjava.util.List; importorg.apache.ibatis.annotations.Param;</p><p>public interface BusinessDao&lt;T&gt; extends BaseDao&lt;T&gt;{ List&lt;T&gt;selectList(@Param(&quot;ew&quot;)Wrapper&lt;T&gt;var1,@Param(&quot;dataScope&quot;)DataScopevar2);</p><p>IPage&lt;T&gt;listPage(IPage&lt;T&gt;var1,@Param(&quot;ew&quot;)Wrapper&lt;T&gt;var2);</p><p>IPage&lt;T&gt;listPage(IPage&lt;T&gt;var1,@Param(&quot;ew&quot;)Wrapper&lt;T&gt;var2,@Param(&quot;dataScope&quot;)DataScopevar3);</p><p>IPage&lt;T&gt;selectPage(IPage&lt;T&gt;var1,@Param(&quot;ew&quot;)Wrapper&lt;T&gt;var2,@Param(&quot;dataScope&quot;)DataScopevar3); }</p><p>import org.apache.ibatis.annotations.Param; import java.util.List; /**</p><ul><li>&lt;p&gt;</li><li>项目进度管理表 Mapper 接口</li><li>&lt;/p&gt;</li><li></li><li>@author 张三</li><li>@since 2023-05-26 <em>/ public interface ProjectManagementDao extends BusinessDao&lt;ProjectManagement&gt; { /</em>*</li><li>进度报表统计 -- 根据年份，统计地区为查询条件</li><li>1.项目总个数</li><li>2.已开工个数：建设进度字段不为null</li><li>3.已完工个数 <em>/ ManagementCountVo getCount(@Param(&quot;countYear&quot;) String countYear, @Param(&quot;countRegion&quot;) String countRegion); /</em>*</li><li>根据年份，统计地区为查询条件 计划投资报表 <em>/ List&lt;CountVo&gt; getSourcesCount(@Param(&quot;countYear&quot;) String countYear, @Param(&quot;countRegion&quot;) String countRegion,@Param(&quot;doneInvest&quot;) String doneInvest); /</em>*</li><li>根据年份，统计地区为查询条件 计划投资报表 <em>/ Integer getElseCount(@Param(&quot;countYear&quot;) String countYear, @Param(&quot;countRegion&quot;) String countRegion,@Param(&quot;doneInvest&quot;) String doneInvest); /</em>*</li><li>按照年份来统计总数 */ Integer getYearCount(@Param(&quot;year&quot;)String year); }</li></ul><p>这是一个使用了 MyBatis 框架的 Java 接口，定义了与数据库操作相关的方法。在这个例子中，这些方法都是与 &quot;项目进度管理表&quot; 相关的。下面，我会详细解释 getCount 方法及其相关的注解和参数。</p><ol><li>getCount 方法：</li></ol><p>这个方法的作用是获取特定年份和地区的项目进度统计信息。它返回一个 ManagementCountVo 对象，这个对象可能包含如下的信息：</p><p>项目总个数 已开工个数（建设进度字段不为null） 已完工个数 这些信息可能是基于某个年份和地区进行的统计。</p><ol start="2"><li>@Param 注解：</li></ol><p>@Param 是 MyBatis 的一个注解，它用于将方法参数传递给映射 SQL 语句。在 MyBatis 的 SQL 映射语句中，可以使用 #{paramName} 的形式来引用这些参数。</p><p>在这个 getCount 方法中，@Param 注解用于将方法的参数（countYear 和 countRegion）传递给 SQL 映射语句。</p><ol start="3"><li>参数：</li></ol><p>countYear: 这个参数应该是一个表示年份的字符串，例如 &quot;2023&quot;。它应该是用来指定要获取哪一年的项目进度统计信息的。 countRegion: 这个参数应该是一个表示地区的字符串，例如 &quot;北京&quot;。它应该是用来指定要获取哪个地区的项目进度统计信息的。 请注意，实际的 SQL 映射语句（在 MyBatis 的 Mapper XML 文件或者注解中）决定了这些参数如何被使用，以及 getCount 方法的具体行为。</p><p>&lt;mapper namespace=&quot;com.zhsl.sgc.dao.ProjectManagementDao&quot;&gt;</p><p>&lt;!--进度报表统计 根据年份，统计地区为查询条件 1.项目总个数 2.已开工个数：建设进度字段不为null 3.已完工个数 --&gt; &lt;select id=&quot;getCount&quot; resultType=&quot;com.zhsl.sgc.vo.ManagementCountVo&quot;&gt; SELECT count(1) AS projectNum, (SELECT COUNT(1) FROM SGC_PROJECT_MANAGEMENT WHERE BTSCHEDULE IS NOT NULL AND SCHEDULE IS NOT NULL) as inServiceNum, (SELECT COUNT(1) FROM SGC_PROJECT_MANAGEMENT WHERE BTSCHEDULE = &#39;D&#39; AND SCHEDULE = &#39;100%&#39;) as completedNum FROM SGC_PROJECT_MANAGEMENT &lt;where&gt; &lt;choose&gt; &lt;when test=&quot;countYear != null and countYear != &#39;&#39; &quot;&gt; and THEIRYEAR = #{countYear} &lt;/when&gt; &lt;otherwise&gt; and THEIRYEAR = DATE_FORMAT(NOW(),&#39;%Y&#39;) &lt;/otherwise&gt; &lt;/choose&gt; &lt;if test=&quot;countRegion != null and countRegion != &#39;&#39;&quot;&gt; and THEIRDISTRICT like concat(&#39;%&#39;,#{countRegion},&#39;%&#39;) &lt;/if&gt; &lt;/where&gt; &lt;/select&gt;</p><p>这是一个 MyBatis 的 XML 映射文件中的 &lt;select&gt; 标签，用于定义 SQL 查询语句。它和具体的数据库 SQL 语法结合，提供了一种灵活而强大的数据查询方式。以下是该 &lt;select&gt; 标签内部各部分的解释：</p><p>id=&quot;getCount&quot;: 这指定了该 SQL 查询语句与 ProjectManagementDao 接口中的哪个方法相对应，即 getCount 方法。</p><p>resultType=&quot;com.zhsl.sgc.vo.ManagementCountVo&quot;: 这指定了该 SQL 查询语句的返回结果应该被封装到哪个 Java 类中，即 ManagementCountVo 类。</p><p>SELECT count(1) AS projectNum: 这个查询统计了 SGC_PROJECT_MANAGEMENT 表中的总记录数，并将结果存储在别名为 projectNum 的返回字段中。</p><p>SELECT COUNT(1) FROM SGC_PROJECT_MANAGEMENT WHERE BTSCHEDULE IS NOT NULL AND SCHEDULE IS NOT NULL: 这个子查询统计了 SGC_PROJECT_MANAGEMENT 表中 BTSCHEDULE 和 SCHEDULE 字段都不为 NULL 的记录数，并将结果存储在别名为 inServiceNum 的返回字段中。</p><p>SELECT COUNT(1) FROM SGC_PROJECT_MANAGEMENT WHERE BTSCHEDULE = &#39;D&#39; AND SCHEDULE = &#39;100%&#39;: 这个子查询统计了 SGC_PROJECT_MANAGEMENT 表中 BTSCHEDULE 字段为 &#39;D&#39;，且 SCHEDULE 字段为 &#39;100%&#39; 的记录数，并将结果存储在别名为 completedNum 的返回字段中。</p><p>&lt;where&gt;: 它生成 WHERE 子句。</p><p>&lt;choose&gt;, &lt;when&gt;, &lt;otherwise&gt;: 这三个标签是 MyBatis 的条件判断标签，等同于 Java 中的 switch 和 if-else 语句。</p><p>&lt;if&gt;: MyBatis 的条件判断标签，等同于 Java 中的 if 语句。</p><p>对于具体的 SQL 语句和 MyBatis 标签的使用，要根据实际的数据表结构和业务需求来定。所以这个 SQL 查询语句可能不适用于其他的数据表。如果你有其他数据表的相关需求，可能需要编写新的 SQL 查询语句和 MyBatis XML 映射文件来满足这些需求。</p><p>注意：你给出的代码中 likt 应该是拼写错误，应该为 like。</p><p>在MyBatis的映射文件中，&lt;where&gt;、&lt;if&gt;、&lt;choose&gt;、&lt;when&gt;、&lt;otherwise&gt;等元素可以被用来动态生成SQL语句。</p><p>&lt;where&gt;: 用于生成一个where子句，自动处理&quot;where&quot;关键字和&quot;and&quot;或&quot;or&quot;关键字的位置，使得生成的SQL更为准确。</p><p>&lt;if&gt;: 用于进行条件判断。&quot;test&quot;属性中的内容就是判断的条件。当test中的表达式为true时，会包含该&lt;if&gt;标签内的SQL片段，否则不会包含。例如，test=&quot;countRegion != null and countRegion != &#39;&#39;&quot;，意味着当countRegion参数不为null并且不为空字符串时，才会在生成的SQL中添加 and THEIRDISTRICT like concat(&#39;%&#39;,#{countRegion},&#39;%&#39;)这段SQL。</p><p>&lt;choose&gt;、&lt;when&gt;、&lt;otherwise&gt;: 与Java中的switch-case-default结构类似，用于在多个条件中选择一个。&lt;when&gt;表示当某个条件为真时要做的事情，&lt;otherwise&gt;表示当所有&lt;when&gt;中的条件都不为真时做的事情。</p><p>在你给出的例子中，test属性被用来判断是否要包含特定的SQL片段。如果countYear不为null且不为空字符串，则在生成的SQL中添加and THEIRYEAR = #{countYear}；否则，添加and THEIRYEAR = DATE_FORMAT(NOW(),&#39;%Y&#39;)。同样地，只有当countRegion不为null且不为空字符串时，才在生成的SQL中添加and THEIRDISTRICT like concat(&#39;%&#39;,#{countRegion},&#39;%&#39;)。这样做可以让我们的SQL根据不同的参数动态地变化，从而更灵活地应对不同的查询需求。</p></div>',1)])])}const E=e(u,[["render",p]]);export{m as __pageData,E as default};
